window.FILM_WORK_PROMPTS={"work_id":"src-0e6ca78d236b043e","records":[{"work_id":"src-0e6ca78d236b043e","frame_id":"FG-e5f9dfebe8561d1b","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking007.jpg","source_page":"https://film-grab.com/2020/08/16/erik-the-conqueror/","scene":"黄昏海边，一名长发女子坐于前景，怀抱浅色物体。右侧一人身披宽大浅色长袍，身体前倾靠近女子。背景为深色海面与紫红色云层。","analysis":"画面主体为两人，仅可见上半身。右侧人物因长袍覆盖显得体积较大，呈俯身姿态。背景天空占据画面上半部，呈现紫红与暗蓝的渐变，云层厚重。光线昏暗，人物面部及衣物受暖色光照射，与深色背景形成对比。","prompt":"低分辨率电影静帧，黄昏海边场景。前景左侧一名长发女子坐着，身穿浅色长袖上衣，怀中抱着一个模糊的浅色团状物体。右侧一名人物身披巨大的米黄色半透明长袍，身体向左前方大幅度倾斜，头部靠近女子。背景是深黑色的海平面，上方是紫红色与暗蓝色交织的厚重云层。整体色调偏暖，光线集中在人物身上，营造出一种压抑而神秘的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:19:02-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking007.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-c7c580346b0917e2","origin":"visual"},{"work_id":"src-0e6ca78d236b043e","frame_id":"FG-be0452b21bd727ec","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking020.jpg","source_page":"https://film-grab.com/2020/08/16/erik-the-conqueror/","scene":"昏暗洞穴内，两名人物在中央对峙，背景矗立着巨大的深色岩石状物体，两侧站立着密集的人群，周围分布着多处明亮的黄色光点。","analysis":"画面采用横向构图，中央两名人物全身可见，呈站立姿态，身形在巨大的背景岩石前显得渺小。背景岩石占据画面上半部大部分空间，质感粗糙。两侧人群密集排列，形成包围感。光线主要来自周围散布的黄色亮区，照亮了人物轮廓和地面，整体色调偏暖，明暗对比强烈，营造出压抑且紧张的氛围。","prompt":"低分辨率宽幅画面，昏暗的洞穴或地下空间。画面中央，两名全身可见的人物站立对峙，左侧人物身形较小，右侧人物身形较大，均呈战斗姿态。背景是一堵巨大的、纹理粗糙的深色岩石或山体，占据了画面上方大部分区域。岩石两侧及后方站立着密集的人群，人物轮廓模糊，形成半包围结构。环境中有许多明亮的黄色光点散布在人群中和地面，照亮了中央区域。地面呈深褐色，前景有模糊的物体轮廓。整体色调为暖黄与深黑的对比，光影斑驳，气氛紧张。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:19:18-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking020.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-73065d84fc984aa5","origin":"visual"},{"work_id":"src-0e6ca78d236b043e","frame_id":"FG-a93c6b3aae7f3b30","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking033.jpg","source_page":"https://film-grab.com/2020/08/16/erik-the-conqueror/","scene":"两名男子在石墙与圆形金属门板前近距离对峙。左侧男子身着深色带红边护甲，右侧男子身着深色毛皮衣物，右手持短刃抵住左侧男子颈部，两人面部贴近。","analysis":"画面为横向构图，主体为两名男子的上半身及头部，占据画面中心大部分区域。背景可见圆形金属门板及铆钉细节，左侧有模糊的浅色物体。光线从右侧照射，右侧男子面部及发色较亮，左侧男子面部处于阴影中，明暗对比强烈。人物比例接近，右侧男子因持刃动作身体略微前倾，整体色调偏暖黄与深褐。","prompt":"低分辨率电影静帧，横向构图。画面中心两名男子近距离对峙，左侧男子深色头发，身着深色带红边护甲，面部处于阴影中，神情凝重；右侧男子金发，身着深色毛皮衣物，面部受光较亮，右手持短刃抵住左侧男子颈部。背景为石墙与圆形金属门板，门板上有铆钉细节，左侧有模糊浅色物体。光线从右侧照射，明暗对比强烈，色调偏暖黄与深褐，人物上半身及头部清晰可见，环境占比约三分之一。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:19:45-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking033.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-563f4a0f47f23428","origin":"visual"},{"work_id":"src-0e6ca78d236b043e","frame_id":"FG-fc4ff4dbb6a75a28","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking046.jpg","source_page":"https://film-grab.com/2020/08/16/erik-the-conqueror/","scene":"昏暗洞穴内，一人站立于中央，双手高举过头。地面散落多具倒地的人形，背景是巨大的树根与岩壁，整体色调偏暗绿与土黄。","analysis":"画面采用中心构图，站立人物位于视觉焦点，周围环绕倒地的人形。人物全身可见，但面部细节模糊。背景巨大的树根结构占据画面上半部分，形成压迫感。光线昏暗，主要光源似乎来自上方或前方，照亮了站立人物的上半身和地面，周围区域则陷入阴影，色彩以暗绿、土黄和深褐为主。","prompt":"昏暗的洞穴场景，地面为土黄色，散落着多具倒地的人形，姿态各异。画面中央站立着一名人物，全身可见，双手高举过头顶，似乎正举着某种物体。背景是巨大的、盘根错节的树根结构，延伸至画面顶部，岩壁呈现暗绿色调。光线昏暗，主要照亮中央站立的人物和地面，周围区域处于阴影中。色彩以暗绿、土黄和深褐为主，营造出压抑、神秘的氛围。人物轮廓清晰，但面部细节模糊。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:20:10-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking046.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-20c0d378ac110955","origin":"visual"},{"work_id":"src-0e6ca78d236b043e","frame_id":"FG-fc3f2a6a2dfb16b9","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking059.jpg","source_page":"https://film-grab.com/2020/08/16/erik-the-conqueror/","scene":"昏暗洞穴环境中，左侧金发女子侧身站立，右侧男子半身没入深色岩石状物质中，两人面对面，女子手臂伸向男子，背景有模糊人影。","analysis":"横向构图，人物占据画面左右两侧，中间由深色岩石状物质隔开。左侧女子可见上半身，右侧男子仅头部和肩部露出。光线从上方投射，照亮人物面部和手臂，背景昏暗。色彩以暖黄肤色、金发、深褐岩石和暗红衣物为主，明暗对比强烈，营造出压抑紧张的氛围。","prompt":"低分辨率电影静帧，昏暗洞穴场景。左侧一名金发高马尾女子侧身站立，身穿深色短袖，身体朝向右侧，手臂伸出。右侧一名短发男子半身没入深褐色粗糙岩石状物质中，仅露出头部和肩部，面部朝向左侧女子。两人面对面，距离较近。背景深处有模糊的红色衣物人影。光线从上方投射，照亮人物面部和手臂，形成强烈的明暗对比。色彩以暖黄肤色、金发、深褐岩石和暗红衣物为主，画面质感粗糙，氛围压抑紧张。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:20:56-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking059.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-1b2f22d2086e9f9c","origin":"visual"},{"work_id":"src-0e6ca78d236b043e","frame_id":"FG-bf313e170791cc08","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking008.jpg","source_page":"https://film-grab.com/2020/08/16/erik-the-conqueror/","scene":"黑暗环境中，数个骷髅头骨与躯干骨骼悬挂在交错的枯枝与藤蔓之间，呈现出一种阴森、静止的陈列状态。","analysis":"画面采用横向构图，主体为悬挂的骨骼。可见范围包括完整的头骨和部分躯干骨骼，骨骼在画面中占据主要视觉比重。视角接近平视，光线昏暗，仅有微弱的光源照亮骨骼表面，形成强烈的明暗对比。色彩以深褐、土黄和暗绿为主，枯枝的冷色调与骨骼的暖色调交织，营造出压抑的视觉层次。","prompt":"这是一张低分辨率的暗调画面，主体是悬挂在黑暗中的多具骷髅。画面中央及两侧分布着数个完整的头骨，下方连接着部分躯干骨骼，骨骼表面呈现出陈旧的土黄色与褐色质感。背景是极度昏暗的深黑色，大量细长的枯枝和藤蔓在骨骼前方与后方交错穿插，形成复杂的网状遮挡。微弱的光线从上方或侧面投射，勾勒出骨骼的轮廓，使眼窝和鼻腔的阴影更加深邃。整体色调阴冷，以暗绿、深褐和黑色为主，营造出一种原始、荒凉且令人不安的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T20:07:51+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking008.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-e47004196c041127","origin":"visual"},{"work_id":"src-0e6ca78d236b043e","frame_id":"FG-79369146e4aae5b0","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking021.jpg","source_page":"https://film-grab.com/2020/08/16/erik-the-conqueror/","scene":"两名金发女性并排位于画面中央的矩形洞口内，仅露出头部和肩部。她们身后是昏暗的木质结构，洞口四周被粗糙的红褐色岩壁或土墙包围，占据了画面的大部分面积。","analysis":"构图采用中心对称，矩形洞口形成天然画框。人物仅可见头部及肩颈部分，相对于巨大的红褐色墙体显得较小。视角平视，光线从前方照亮人物面部，使其在昏暗背景中突出。色彩以暖红褐色为主调，人物肤色与金发在暗部衬托下显得明亮，形成强烈的明暗对比。","prompt":"低分辨率画面，中心构图。画面主体是一个嵌入粗糙红褐色岩壁或土墙中的矩形木质窗口。窗口内并排站立着两名金发女性，仅可见头部和肩部。左侧女性头发向后梳理，右侧女性头发盘起，两人均面向前方，面部被前方光线照亮，呈现暖色调。窗口内部背景昏暗，隐约可见深色的木质横梁或结构。窗口四周是占据画面大部分面积的红褐色粗糙表面，纹理模糊，呈现出洞穴或地下空间的质感。整体色调偏暖，以红褐色和暗棕色为主，人物面部是画面中最亮的区域。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T20:08:02+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking021.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-45c5fd2f3068f515","origin":"visual"},{"work_id":"src-0e6ca78d236b043e","frame_id":"FG-fc412d1606b801c4","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking034.jpg","source_page":"https://film-grab.com/2020/08/16/erik-the-conqueror/","scene":"一名头戴白色头巾与黑色外罩的人物上半身，面部朝向左前方。背景左侧为大面积紫蓝色块，右侧为暗红褐色垂直结构，人物占据画面中心。","analysis":"人物头部与肩部位于画面中央，面部朝向左侧，视线平视。背景左侧为均匀的紫蓝色，右侧为暗红褐色垂直色块，形成冷暖对比。光线从左侧照射，使人物面部左侧较亮，右侧及黑色头罩部分处于阴影中。画面分辨率较低，边缘轮廓柔和，色彩过渡平滑。","prompt":"低分辨率电影静帧，画面中央为一名人物上半身，头戴白色头巾，外罩黑色头罩，额前有金色饰带。人物面部朝向左前方，神情平静。背景左侧为大面积紫蓝色，右侧为暗红褐色垂直结构。光线从左侧照射，人物面部左侧受光，右侧处于阴影中。色彩对比鲜明，轮廓柔和，无多余细节。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T20:08:12+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking034.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-7b053db1ea89b6bf","origin":"visual"},{"work_id":"src-0e6ca78d236b043e","frame_id":"FG-f12b5b43ed069fae","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking047.jpg","source_page":"https://film-grab.com/2020/08/16/erik-the-conqueror/","scene":"昏暗木质背景前，两名金发人物近距离相对。左侧人物赤裸上身，右侧人物佩戴红色头带，两人面部几乎贴近，视线交汇。","analysis":"构图紧凑，人物占据画面主体。左侧人物可见头部及肩胸，右侧人物可见头部及肩颈。视角平视，光线从上方投射，在面部形成明暗对比。色调以暖黄和深褐为主，红色头带与暗色背景形成视觉焦点。","prompt":"低分辨率画面，昏暗的木质结构背景中，两名金发人物近距离面对面。左侧人物为男性，金发向后梳理，赤裸上身，皮肤呈现古铜色，面部朝向右侧。右侧人物为女性，金发高束成马尾，额头佩戴红色细带，面部朝向左侧。两人头部几乎接触，视线相对。背景由深褐色木板构成，光线从上方投射，在人物面部和肩部形成高光，其余部分处于阴影中。整体色调偏暖，以黄色、褐色和暗红色为主，画面质感粗糙，具有复古胶片感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T20:08:21+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking047.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-61a968fea3c24e72","origin":"visual"},{"work_id":"src-0e6ca78d236b043e","frame_id":"FG-dea52d22653c9368","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking060.jpg","source_page":"https://film-grab.com/2020/08/16/erik-the-conqueror/","scene":"画面主体为占据上方约一半面积的深色海面，白色浪花在岸边破碎。下方是粗糙的岩石岸线，一名人物站立在岩石与前景深色木质平台之间，身形在广阔环境中显得渺小。","analysis":"构图呈现明显的水平分层，上方为翻涌的海浪，下方为静止的岩石与平台。人物位于画面中轴线偏右位置，全身轮廓可见，呈站立姿态，相对于巨大的海浪和前景平台，人物比例极小。视角为轻微俯视，光线昏暗，整体色调偏向冷灰与深褐，海浪的白色泡沫与暗色海水形成对比，前景平台处于阴影中。","prompt":"低分辨率电影静帧，昏暗色调。画面上半部分是深灰色的海面，白色浪花在岸边破碎，占据约50%画面。中部是粗糙的灰褐色岩石岸线，一名人物站立在岩石上，全身可见，身形渺小，呈站立姿态。前景是深色的木质平台或甲板，占据画面底部约三分之一，纹理模糊。整体光线低沉，色彩以冷灰、深褐和白色浪花为主，人物位于中轴线偏右，与广阔的海浪环境形成强烈的大小对比。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T20:08:32+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/erikviking060.jpg","observed_dimensions":[500,215],"source_thumbnail_dimensions":[500,215],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-8ed1c80c4b8354c1","origin":"visual"}]};